{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "A close analogue sharing the acrylamide-piperidine and heteroaryl ether core achieved a Kp,uu of 0.37 in a constant-infusion rat study and was classified as permeable, indicating meaningful brain exposure despite incomplete equilibration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Oral BTK inhibitors of this chemotype (tolebrutinib, fenebrutinib, evobrutinib) were detected at pharmacologically relevant concentrations in non-human primate CSF, demonstrating CNS access after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A structurally related compound 27 showed favorable brain exposure measured by Kp,uu in rat, supporting CNS access for this inhibitor scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tirabrutinib, a closely related covalent BTK inhibitor, reached measurable unbound brain concentrations (brain Cmax 28.9 ng/mL) with an unbound brain-to-plasma ratio of 8.5% and was labeled permeable, showing meaningful CNS uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A high-transfer analogue achieved a Brain:Blood ratio of 6.8 in rat in vivo exposure studies and was classified as high permeability, supporting that related inhibitors can achieve robust CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Despite physicochemical warnings about high molecular weight, high logP, and possible efflux, the closest experimental analogues—covalent BTK inhibitors sharing the acrylamide-piperidine and biaryl-ether heteroaromatic core—consistently show measurable brain/CSF exposure in rats, non-human primates, and humans (Kp,uu ~0.37, CSF detection, brain-to-plasma ratios >1 or 8.5% unbound). Therefore the query is predicted to have meaningful CNS access after systemic administration.",
  "evidence_gaps": [
    "No direct Kp,uu or CSF measurement is available for the exact query molecule.",
    "Efflux-transporter contribution is not directly quantified for the query.",
    "High lipophilicity may lower unbound brain fraction even if total brain penetration is adequate."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

